$ErrorActionPreference = "Stop"

Write-Host "=== SaborFlow - Sessao deslizante de 10 dias ===" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "package.json")) {
    throw "Execute este script na pasta principal do projeto SaborFlow."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Sessao10Dias-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "lib\auth.ts",
    "proxy.ts",
    "app\api\auth\logout\route.ts",
    "app\api\auth\2fa\verify\route.ts"
)

foreach ($file in $targets) {
    if (Test-Path $file) {
        $backupPath = Join-Path $backupRoot $file
        $backupDir = Split-Path $backupPath -Parent
        New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
        Copy-Item $file $backupPath -Force
    }
}

Write-Host "Backup criado em:" -ForegroundColor Green
Write-Host $backupRoot
Write-Host ""

function Write-Base64File {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $directory = Split-Path $Path -Parent
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), $bytes)
}

Write-Host "Gravando lib\auth.ts..."
Write-Base64File -Path "lib\auth.ts" -Base64 ""

Write-Host "Gravando proxy.ts..."
Write-Base64File -Path "proxy.ts" -Base64 ""

Write-Host "Gravando app\api\auth\logout\route.ts..."
Write-Base64File -Path "app\api\auth\logout\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\2fa\verify\route.ts..."
Write-Base64File -Path "app\api\auth\2fa\verify\route.ts" -Base64 ""

Write-Host ""
Write-Host "Sessao deslizante aplicada localmente." -ForegroundColor Green
Write-Host "Regra: cada uso valido renova a sessao por mais 10 dias." -ForegroundColor Green
Write-Host "Logout manual continua encerrando a sessao imediatamente." -ForegroundColor Green
Write-Host ""
Write-Host "Nenhuma migration foi criada ou executada." -ForegroundColor Yellow
Write-Host ""
git status --short
